// Generated by tools/gen_h753_runs.py: edit RUNS there, not this file.

//! Run D: UART4 on the PC10/PC11 link USART3 uses in run B, and UART7 on
//! its JTAG pins, PA15 and PB3. The full check list on each, then both
//! streaming at once.
//!
//! RTIC owns every interrupt; FerroHAL only enables each UART's and its
//! DMA channels' own interrupt bits. Each UART is one shared resource, served by
//! its handlers and used by the `checks` task under RTIC's lock, one call at
//! a time (`tests::Locked`; `docs/design/uart-ownership.md`). Each vector in
//! use, and what serves it:
//!
//! | Vector | Serves | Priority |
//! | --- | --- | --- |
//! | `UART4`, `DMA2_STREAM1`, `DMA1_STREAM2` | UART4's `on_interrupt` | 2 |
//! | `UART7`, `DMA1_STREAM3`, `DMA2_STREAM6` | UART7's `on_interrupt` | 2 |
//! | `SPI1` | RTIC, dispatching the priority 1 `checks` task | 1 |

#![no_std]
#![no_main]

#[path = "../board.rs"]
mod board;
#[path = "../../../common/tests.rs"]
mod tests;

use defmt_rtt as _;
use panic_probe as _;

#[rtic::app(device = ferrohal_stm32::device, peripherals = true, dispatchers = [SPI1])]
mod app {
    use ferrohal_stm32::{
        chip::Interrupt,
        uart::{Config, Uart, Vectors},
    };

    use crate::{
        board::{self, RX_RING, TX_BUFFER},
        tests::{self, Locked, Loop, Report},
    };

    const PLAIN: Config = Config::new(ferrohal_stm32::time::Hertz(115_200));

    #[shared]
    struct Shared {
        uart4: Uart<board::Uart4D>,
        uart7: Uart<board::Uart7D>,
    }

    #[local]
    struct Local {
        vectors_uart4: Vectors,
        vectors_uart7: Vectors,
        led: board::Led,
    }

    #[init]
    fn init(cx: init::Context) -> (Shared, Local) {
        let mut core = cx.core;
        // The cycle counter, for the wait-bound check.
        core.DCB.enable_trace();
        core.DWT.enable_cycle_counter();
        // The buffers' block is non-cacheable before anything could cache it.
        board::dma_region(&mut core);

        let mut run = match board::run_d(cx.device) {
            Ok(run) => run,
            Err(error) => defmt::panic!("clocks: {}", error),
        };
        // `freeze` must land on the tree worked out while compiling.
        defmt::assert_eq!(run.rcc.clocks(), board::CLOCKS);
        defmt::info!("run D, clocks: {}", board::CLOCKS);

        let mut buffers = board::dma_buffers().into_iter();
        let uart4 = board::open(
            &mut run.rcc,
            "UART4 PC10->PC11",
            run.uart4,
            &PLAIN,
            buffers.next().unwrap(),
        );
        let uart7 = board::open(
            &mut run.rcc,
            "UART7 PA15->PB3",
            run.uart7,
            &PLAIN,
            buffers.next().unwrap(),
        );

        let vectors_uart4 = uart4.vectors();
        let vectors_uart7 = uart7.vectors();
        checks::spawn().ok();
        (
            Shared { uart4, uart7 },
            Local {
                vectors_uart4,
                vectors_uart7,
                led: run.led,
            },
        )
    }

    #[task(binds = UART4, priority = 2, shared = [uart4])]
    fn uart4_line(mut cx: uart4_line::Context) {
        cx.shared.uart4.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA2_STREAM1, priority = 2, shared = [uart4])]
    fn uart4_rx(mut cx: uart4_rx::Context) {
        cx.shared.uart4.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM2, priority = 2, shared = [uart4])]
    fn uart4_tx(mut cx: uart4_tx::Context) {
        cx.shared.uart4.lock(|uart| tests::serve(uart));
    }

    #[task(binds = UART7, priority = 2, shared = [uart7])]
    fn uart7_line(mut cx: uart7_line::Context) {
        cx.shared.uart7.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA1_STREAM3, priority = 2, shared = [uart7])]
    fn uart7_rx(mut cx: uart7_rx::Context) {
        cx.shared.uart7.lock(|uart| tests::serve(uart));
    }

    #[task(binds = DMA2_STREAM6, priority = 2, shared = [uart7])]
    fn uart7_tx(mut cx: uart7_tx::Context) {
        cx.shared.uart7.lock(|uart| tests::serve(uart));
    }

    #[task(priority = 1, shared = [uart4, uart7], local = [vectors_uart4, vectors_uart7, led])]
    async fn checks(cx: checks::Context) {
        tests::set_cpu_hz(board::CLOCKS.cpu.0);
        let mut report = Report::new();
        report.check_for(
            "UART4 PC10->PC11",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_uart4),
        );
        report.check_for(
            "UART7 PA15->PB3",
            "UART-003 RESOURCE-001",
            "vectors enabled",
            tests::vectors_verified(cx.local.vectors_uart7),
        );
        let mut uart4 = Locked(cx.shared.uart4);
        let mut uart7 = Locked(cx.shared.uart7);

        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "UART4 PC10->PC11",
                uart: &mut uart4,
            },
            &PLAIN,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA2_STREAM1),
            &mut tests::nvic_mask_all([
                Interrupt::UART4,
                Interrupt::DMA2_STREAM1,
                Interrupt::DMA1_STREAM2,
            ]),
            true,
        );
        tests::full_suite(
            &mut report,
            &mut Loop {
                name: "UART7 PA15->PB3",
                uart: &mut uart7,
            },
            &PLAIN,
            RX_RING,
            TX_BUFFER,
            &mut tests::nvic_mask(Interrupt::DMA1_STREAM3),
            &mut tests::nvic_mask_all([
                Interrupt::UART7,
                Interrupt::DMA1_STREAM3,
                Interrupt::DMA2_STREAM6,
            ]),
            true,
        );

        report.check_for(
            "UART4 + UART7",
            "UART-002",
            "8 KiB each, all at once",
            tests::streams(
                &mut [
                    &mut Loop {
                        name: "UART4 PC10->PC11",
                        uart: &mut uart4,
                    },
                    &mut Loop {
                        name: "UART7 PA15->PB3",
                        uart: &mut uart7,
                    },
                ],
                8 * 1024,
            ),
        );

        let led = cx.local.led;
        tests::finish(&report, || led.set_high());
    }
}
